{"file_text": "@namespace sv_147f2c2dba6e4a748506c2aa4e5c97f4.Components.Pages.Settings
@using sv_147f2c2dba6e4a748506c2aa4e5c97f4.Models
@inject ISettingsService SettingsService

<div class="section-content">
    <h3>Appearance Settings</h3>

    @if (_loading)
    {
        <p class="text-muted">Loading appearance settings…</p>
    }
    else
    {
        <div class="appearance-form">
            @* Theme Selector *@
            <div class="mb-4">
                <h5>Theme</h5>
                <div class="d-flex gap-3">
                    @foreach (var theme in _themes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                                   value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="theme-@theme">@theme</label>
                        </div>
                    }
                </div>
            </div>

            @* Font Size Selector *@
            <div class="mb-4">
                <h5>Font Size</h5>
                <div class="d-flex gap-3">
                    @foreach (var size in _fontSizes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                                   value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="fs-@size">@size</label>
                        </div>
                    }
                </div>
            </div>

            @* Language Dropdown *@
            <div class="mb-4">
                <h5>Language</h5>
                <select class="form-select" style="max-width: 300px"
                        value="@_language"
                        @onchange="e => _language = e.Value?.ToString() ?? _language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang.Key">@lang.Value</option>
                    }
                </select>
            </div>

            @* Compact Mode *@
            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode"
                           checked="@_compactMode"
                           @onchange="e => _compactMode = (bool)(e.Value ?? false)" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            @* Live Preview *@
            <div class="mb-4">
                <h5>Preview</h5>
                <div class="live-preview @GetPreviewClass()">
                    <div class="preview-header">Sample Dashboard</div>
                    <p class="preview-text">
                        This is how your content will appear with the selected settings.
                        The preview updates in real time as you adjust options.
                    </p>
                    <div class="preview-actions">
                        <button class="btn btn-sm btn-primary">Action</button>
                        <button class="btn btn-sm btn-outline-secondary">Cancel</button>
                    </div>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save")
            </button>

            @if (_successMessage is not null)
            {
                <div class="alert alert-success mt-3 fade-in" role="alert">
                    ✅ @_successMessage
                </div>
            }

            @if (_errorMessage is not null)
            {
                <div class="alert alert-danger mt-3" role="alert">
                    ❌ @_errorMessage
                </div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;
    private string? _errorMessage;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];

    private static readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語",
        ["zh"] = "中文",
    };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var settings = await SettingsService.GetAppearanceAsync();
            _theme = settings.Theme;
            _fontSize = settings.FontSize;
            _language = settings.Language;
            _compactMode = settings.CompactMode;
        }
        finally
        {
            _loading = false;
        }
    }

    private string GetPreviewClass()
    {
        var classes = new List<string>();

        classes.Add(_theme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "system" => "preview-system",
            _ => "preview-light",
        });

        classes.Add(_fontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-small",
            "large" => "preview-font-large",
            _ => "preview-font-medium",
        });

        if (_compactMode)
            classes.Add("preview-compact");

        return string.Join(' ', classes);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;
        _errorMessage = null;

        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _successMessage = "Appearance settings saved.";
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to save settings: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }
}
